 44→async function processMassivePdfModification(req, res, company, signers_count) {
 45→    const arrData = req.body.data;
 46→    const fields = req.body.fields;
 47→
 48→    const details = await db.document_packages_details.findMany({
 49→        where: {
 50→            document_package_header_id: parseInt(req.body.documentHeaderId),
 51→            active: "1",
 52→        },
 53→        select: {
 54→            id: true,
 55→            name: true,
 56→            content: true,
 57→        },
 58→    });
 59→
 60→    if (!details || details.length === 0) {
 61→        return res.status(400).json({ status: false, message: 'No se encontraron documentos PDF' });
 62→    }
 63→
 64→    const pdfBuffers = {};
 65→    for (const detail of details) {
 66→        const buffer = await axios.get(detail.content, {
 67→            responseType: 'arraybuffer'
 68→        }).then(response => Buffer.from(response.data));
 69→        pdfBuffers[detail.id] = buffer;
 70→    }
 71→
 72→    const documentPackageHeader = await db.document_packages_header.findFirst({
 73→        where: {
 74→            id: parseInt(req.body.documentHeaderId),
 75→        },
 76→        select: {
 77→            name: true,
 78→            order: true,
 79→            group_signers: {
 80→                select: {
 81→                    user_id: true,
 82→                    order: true,
 83→                    user: {
 84→                        select: {
 85→                            id: true,
 86→                            email: true,
 87→                            firstname: true,
 88→                            lastname: true,
 89→                            id_number: true,
 90→                            id_type: true,
 91→                        }
 92→                    }
 93→                },
 94→            }
 95→        }
 96→    });
 97→
 98→    try {
 99→
100→        for (const obj of arrData) {
101→
102→            let signer_fields = obj.signers;
103→
104→            const predefinedSigners = documentPackageHeader.group_signers.map(signer => ({
105→                signer_order: signer.order,
106→                user_id: signer.user.id,
107→                nombres: signer.user.firstname,
108→                apellidos: signer.user.lastname,
109→                correo: signer.user.email,
110→                documento: signer.user.id_number,
111→                tipo_documento: signer.user.id_type,
112→            }));
113→
114→            signer_fields = [
115→                ...signer_fields,
116→                ...predefinedSigners.filter(predefSigner =>
117→                    !signer_fields.some(signer => signer.user_id === predefSigner.user_id)
118→                )
119→            ];
120→
121→            const variableValues = obj.variableValues || {};
122→
123→            const s3Keys = [];
124→            for (const detail of details) {
125→                const detailFields = fields.filter(f => {
126→                    if (f.pdfId === undefined || f.pdfId === null) return true;
127→                    return parseInt(f.pdfId) === parseInt(detail.id);
128→                });
129→
130→                const pdfDoc = await PDFDocument.load(pdfBuffers[detail.id]);
131→                const modifiedPdf = await modifyPdfWithFields(pdfDoc, detailFields, signer_fields, variableValues);
132→                const s3Key = await uploadToS3(modifiedPdf, company.id);
133→                s3Keys.push({ detailId: detail.id, s3Key, name: detail.name });
134→            }
135→
136→            await db.$transaction(async (prisma) => {
137→                const users = await getUsers(prisma, signer_fields, company.id);
138→
139→                const documentPackageSigner = await createDocumentPackageSigner(
140→                    prisma,
141→                    obj,
142→                    req.body.user_id_creator,
143→                    company.id,
144→                    users[0].id,
145→                    req.body.documentHeaderId,
146→                    req.body.recipients,
147→                    req.body.sendReminder,
148→                    req.body.reminder_days_interval
149→                );
150→
151→                await prisma.document_packages_signers_logs.create({
152→                    data: {
153→                        document_package_signer_id: parseInt(documentPackageSigner.id),
154→                        event_description: "Solicitud de firma enviada",
155→                        ip_address: req.ip ? req.ip : null,
156→                        performed_by_user_id: parseInt(req.body.user_id_creator),
157→                        created_at: new Date(),
158→                    },
159→                });
160→
161→                for (const { s3Key, detailId, name } of s3Keys) {
162→                    await prisma.document_packages_signers_details_values.create({
163→                        data: {
164→                            document_package_detail_id: detailId,
165→                            document_package_signer_id: parseInt(documentPackageSigner.id),
166→                            name: name,
167→                            company_id: parseInt(documentPackageSigner.company_id),
168→                            visibility: 1,
169→                            document_type_id: 1,
170→                            fields: JSON.stringify(fields),
171→                            signers_fields: JSON.stringify(signer_fields),
172→                            modified_content: s3Key,
173→                            s3_key: s3Key,
174→                            created_at: new Date(),
175→                            updated_at: new Date()
176→                        }
177→                    });
178→                }
179→
180→                await sendSignRequests(res, documentPackageSigner, users, company, signer_fields, req.body.name, documentPackageHeader, prisma);
181→            }, {
182→                maxWait: 100000,
183→                timeout: 100000,
184→            });
185→        }
186→
187→        if (!res.headersSent) {
188→            res.status(200).send({
189→                status: true,
190→                data: {
191→                    count: signers_count,
192→                },
193→                message: "Solicitud enviada exitosamente"
194→            });
195→        }
196→
197→    } catch (error) {
198→        console.error('Error processing massive PDF modification:', error);
199→        throw new Error('Error en la modificación masiva del PDF');
200→    }
201→}
