203→async function modifyPdfWithFields(pdfBuffer, fields, signer_fields, variableValues = {}) {
204→    const pdfDoc = pdfBuffer;
205→    const helveticaFont = await pdfDoc.embedFont(StandardFonts.Helvetica);
206→    const timesRomanFont = await pdfDoc.embedFont(StandardFonts.TimesRoman);
207→    const timesRomanBoldFont = await pdfDoc.embedFont(StandardFonts.TimesRomanBold);
208→    const timesRomanItalicFont = await pdfDoc.embedFont(StandardFonts.TimesRomanItalic);
209→    const timesRomanBoldItalicFont = await pdfDoc.embedFont(StandardFonts.TimesRomanBoldItalic);
210→    const helveticaBoldFont = await pdfDoc.embedFont(StandardFonts.HelveticaBold);
211→    const helveticaObliqueFont = await pdfDoc.embedFont(StandardFonts.HelveticaOblique);
212→    const helveticaBoldObliqueFont = await pdfDoc.embedFont(StandardFonts.HelveticaBoldOblique);
213→
214→    const signatureFields = fields.filter(f => f.type !== 'variable');
215→    const variableFieldsList = fields.filter(f => f.type === 'variable');
216→
217→    await Promise.all(signatureFields.map(async (field) => {
218→        const { pageNumber, top, left, width, height, name } = field;
219→        const page = pdfDoc.getPage(pageNumber - 1);
220→        const textWidth = helveticaFont.widthOfTextAtSize(name, 12);
221→        const textHeight = helveticaFont.heightAtSize(12);
222→
223→        const x = left + (width / 2) - (textWidth / 2) - 15;
224→        const y = page.getHeight() - top - (height / 2) - (textHeight / 4);
225→
226→        page.drawText(name, {
227→            x: x,
228→            y: y + 8,
229→            size: 12,
230→            font: helveticaFont
231→        });
232→
233→        const signer = signer_fields.find(s => `[$FIRMA${s.signer_order}]` == name);
234→
235→        if (signer) {
236→            const fullName = `${signer.nombres} ${signer.apellidos}`;
237→            const docType = await getDocumentTypeName(signer.tipo_documento);
238→            const docTypeAndNumber = `${docType.abbreviation}: ${signer.documento}`;
239→
240→            const fullNameWidth = timesRomanFont.widthOfTextAtSize(fullName, 10);
241→            const docTypeAndNumberWidth = timesRomanFont.widthOfTextAtSize(docTypeAndNumber, 10);
242→
243→            const xFullName = x + (textWidth / 2) - (fullNameWidth / 2);
244→
245→            const xDocTypeAndNumber = x + (textWidth / 2) - (docTypeAndNumberWidth / 2);
246→
247→            page.drawText(fullName, {
248→                x: xFullName,
249→                y: y - textHeight - 8,
250→                size: 10,
251→                font: timesRomanFont
252→            });
253→
254→            page.drawText(docTypeAndNumber, {
255→                x: xDocTypeAndNumber,
256→                y: y - textHeight - 22,
257→                size: 10,
258→                font: timesRomanFont
259→            });
260→        }
261→    }));
262→
263→    for (const field of variableFieldsList) {
264→        const { pageNumber, top, left, width, height, name, fontFamily, fontColor, fontWeight, fontStyle } = field;
265→        const page = pdfDoc.getPage(pageNumber - 1);
266→
267→        const varName = name.replace(/\[\$|\]/g, '');
268→        const value = variableValues[varName] || '';
269→
270→        if (!value) continue;
271→
272→        const isBold = fontWeight && parseInt(fontWeight) >= 600;
273→        const isItalic = fontStyle === 'italic';
274→        const isSerif = !fontFamily || fontFamily.includes('Times') || fontFamily.includes('serif') || fontFamily.includes('Garamond') || fontFamily.includes('Georgia') || fontFamily.includes('Lora');
275→
276→        let selectedFont;
277→        if (isSerif) {
278→            if (isBold && isItalic) selectedFont = timesRomanBoldItalicFont;
279→            else if (isBold) selectedFont = timesRomanBoldFont;
280→            else if (isItalic) selectedFont = timesRomanItalicFont;
281→            else selectedFont = timesRomanFont;
282→        } else {
283→            if (isBold && isItalic) selectedFont = helveticaBoldObliqueFont;
284→            else if (isBold) selectedFont = helveticaBoldFont;
285→            else if (isItalic) selectedFont = helveticaObliqueFont;
286→            else selectedFont = helveticaFont;
287→        }
288→
289→        const maxFontSize = Math.min(height * 0.6, 32);
290→        let fontSize = Math.max(8, maxFontSize);
291→
292→        let textWidth = selectedFont.widthOfTextAtSize(value, fontSize);
293→        while (textWidth > width - 4 && fontSize > 6) {
294→            fontSize -= 0.5;
295→            textWidth = selectedFont.widthOfTextAtSize(value, fontSize);
296→        }
297→
298→        const textHeight = selectedFont.heightAtSize(fontSize);
299→
300→        const x = left + (width / 2) - (textWidth / 2);
301→        const y = page.getHeight() - top - (height / 2) + (textHeight / 4);
302→
303→        let color = rgb(0.39, 0.39, 0.38);
304→        if (fontColor && fontColor.startsWith('#')) {
305→            const hex = fontColor.replace('#', '');
306→            const r = parseInt(hex.substring(0, 2), 16) / 255;
307→            const g = parseInt(hex.substring(2, 4), 16) / 255;
308→            const b = parseInt(hex.substring(4, 6), 16) / 255;
309→            color = rgb(r, g, b);
310→        }
311→
312→        page.drawText(value, {
313→            x: x,
314→            y: y,
315→            size: fontSize,
316→            font: selectedFont,
317→            color: color,
318→        });
319→    }
320→
321→    return await pdfDoc.save();
322→}
