336→async function uploadToS3(pdfBuffer, companyId) {
337→
338→    const uniqueId = crypto.randomBytes(16).toString("hex");
339→
340→    const key = `stored_files/${companyId}/${uniqueId}`;
341→    const uploadParams = {
342→        Bucket: process.env.S3_BUCKET,
343→        Key: key,
344→        Body: pdfBuffer,
345→        ContentType: 'application/pdf',
346→    };
347→
348→    await s3Client.send(new PutObjectCommand(uploadParams));
349→    return key; 
350→}
